// Package cisco holds the concrete device type implementation for
// cisco gear ("cisco_switch"). Generated by pleiades forge new-device
// (internal/inventory/devicescaffold); mirrors the hand-written
// internal/inventory/devices/cisco and devices/linux packages.
//
// This package's init registers NewSwitch into the shared
// record.Types registry under "cisco_switch". internal/inventory/factory.go's
// NewItemFactory draws its batteries-included set from that registry
// rather than importing this package by name, so this package is NOT YET
// REACHABLE from the stock binary: internal/inventory/builtins.go's
// blank-import list is what actually triggers a device package's init(),
// and it still only names cisco and linux. Add a blank import of this
// package there (or to your own composition root) before this type is
// reachable through NewItemFactory(). This package itself never imports
// internal/inventory, only the leaf internal/inventory/record package plus
// pkg/inventory, pkg/capability, and pkg/policy, so internal/inventory can
// depend on it (via a future blank import) without a cycle back.
//
// Because this package lives under internal/, it is reachable only from
// code inside this module or a fork of it: Go's internal/ visibility rule
// blocks any other module from importing it at all. This generator is
// repo-contributor tooling, not end-user extensibility; a third-party
// device type arriving from outside this binary needs a separate,
// not-yet-built distribution mechanism, not this one.
//
// Scope: this file gives Switch the structural skeleton every
// device type needs (a record.Base embed, a capability-baseline
// constructor, HasCapability, and the compile-time InventoryItem
// assertion below) but adds no capability-specific accessor methods,
// since pkg/capability.Descriptor's Assert is an opaque function with no
// reflectable method-set metadata this generator could read. Until a
// human adds real accessor methods matching each declared capability's
// interface, HasCapability correctly returns false for all of them: see
// the TODO on Switch below.
package cisco

import (
	"github.com/Subject-Void-LLC/the-pleiades/internal/inventory/record"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/capability"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/inventory"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/policy"
)

func init() {
	record.RegisterType("cisco_switch", NewSwitch)
}

// Switch implements InventoryItem plus, structurally,
// capability.SSHTransportCapable, capability.CiscoIOSCapable, and
// capability.NetworkCLICapable, through the accessor methods below.
//
// It is a sibling of Router rather than a variant of it. Both are IOS
// devices reached over SSH, but the classification tree assigns them
// separately (network_device.cisco.ios.switch inherits the ios level and
// adds NetworkCLICapable), and a switch is what a Catalyst Center reports
// for the "Switches and Hubs" family. Collapsing the two would mean a
// device claiming to be a router because nothing else existed to call it.
//
// The property keys it reads are the ones the Catalyst Center sync plugin
// writes (host, port) plus the generic ones a hand-written hosts.yaml entry
// uses, so a switch onboarded either way behaves identically.
type Switch struct {
	*record.Base
}

var _ inventory.InventoryItem = (*Switch)(nil)

// NewSwitch builds a Switch from rec. It matches the
// record.Constructor shape (func(record.Record) (inventory.InventoryItem,
// error)) record.RegisterType expects.
//
// The capability set is the vendor baseline given to
// "pleiades forge new-device" unioned with rec.Capabilities, per Phase
// 32's capability granularity decision: classification-derived data can
// only add to what this type already asserts about itself, never replace
// it.
func NewSwitch(rec record.Record) (inventory.InventoryItem, error) {
	caps := policy.UnionSlices(
		[]capability.Name{
			capability.Name("SSHTransportCapable"),
			capability.Name("CiscoIOSCapable"),
			capability.Name("NetworkCLICapable"),
		},
		rec.Capabilities,
	)
	base := record.NewBase(rec, caps)
	return &Switch{Base: base}, nil
}

// HasCapability checks the declared classification AND the structural
// registry assertion, so a true result is a guarantee, not a hope.
func (c *Switch) HasCapability(name capability.Name) bool {
	return c.Declares(name) && capability.Implements(c, name)
}

// SSHHost returns the configured management host for this switch.
func (c *Switch) SSHHost() string {
	host, _ := c.Properties().String("host")
	return host
}

// SSHPort returns the configured SSH port, defaulting to 22.
func (c *Switch) SSHPort() int {
	if port, ok := c.Properties().Int("port"); ok && port != 0 {
		return port
	}
	return 22
}

// IOSVersion returns the detected or configured IOS firmware version.
//
// It prefers the key a Catalyst Center sync writes and falls back to the
// generic one a hand-written inventory entry uses, so the same accessor
// answers for a switch onboarded either way.
func (c *Switch) IOSVersion() string {
	if v, ok := c.Properties().String("catalyst_software_version"); ok && v != "" {
		return v
	}
	v, _ := c.Properties().String("ios_version")
	return v
}

// SupportsNETCONF reports whether NETCONF/YANG is enabled on this switch.
func (c *Switch) SupportsNETCONF() bool {
	v, _ := c.Properties().Bool("netconf_enabled")
	return v
}

// CLIPrompt returns the switch's configured CLI prompt string, the
// structural half of capability.NetworkCLICapable.
func (c *Switch) CLIPrompt() string {
	v, _ := c.Properties().String("cli_prompt")
	return v
}
